import{EventEmitter}from"node:events";export class Script{static cache=new Map;static emitter=new EventEmitter;static Load(t,e=1e4){if(Script.cache.has(t))return Script.cache.get(t);const r=new Promise((r,c)=>{if(document.querySelector(`script[src="${t}"]`))return Script.emitEvent("loaded",t),void r();const i=document.createElement("script");i.type="text/javascript",i.defer=!0,i.src=t;const a=setTimeout(()=>{Script.emitEvent("timeout",t),c(new Error(`Script yükleme zaman aşımına uğradı: ${t}`))},e);i.onload=()=>{clearTimeout(a),Script.emitEvent("loaded",t),r()},i.onerror=()=>{clearTimeout(a),Script.emitEvent("error",t),c(new Error(`Script yüklenemedi: ${t}`))},document.head.appendChild(i)});return Script.cache.set(t,r),r}static LoadAll(t,e=1e4){const r=t.map(t=>Script.Load(t,e));return Promise.all(r)}static async LoadSequential(t,e=1e4){for(const r of t)await Script.Load(r,e)}static clearCache(t){Script.cache.delete(t)}static clearAllCache(){Script.cache.clear()}static onEvent(t,e){Script.emitter.on(t,e)}static onceEvent(t,e){Script.emitter.once(t,e)}static removeEvent(t,e){Script.emitter.removeListener(t,e)}static emitEvent(t,e){const r={event:t,url:e};Script.emitter.emit(t,r)}}